/** The dye closest in colour to a block (banner cloth that matches a board or a letter material). */
export function dyeOf(blockName) {
  const c = colourOf(blockName);
  if (!c) return "white";
  return Object.entries(DYE_RGB).map(([d, v]) => [d, v.reduce((s, x, i) => s + (x - c[i]) ** 2, 0)]).sort((a, b) => a[1] - b[1])[0][0];
}
const bannerNbt = (patterns) => tg.compound({ id: tg.string("minecraft:banner"), patterns: tg.list("compound", patterns.map(([p, c]) => ({ pattern: tg.string(`minecraft:${p}`), color: tg.string(c) }))) });
const signNbt = (lines, { dataVersion = 4189, color = "black", glow = false } = {}) => {
  const msg = (s) => (dataVersion >= 4325 ? String(s ?? "") : JSON.stringify({ text: String(s ?? "") }));
  const side = (ls) => ({ messages: tg.list("string", [0, 1, 2, 3].map((i) => msg(ls[i]))), color: tg.string(color), has_glowing_text: tg.byte(glow ? 1 : 0) });
  return tg.compound({ id: tg.string("minecraft:sign"), is_waxed: tg.byte(0), front_text: tg.compound(side(lines)), back_text: tg.compound(side([])) });
};
/** Split text over n signs, whole words per sign where possible (up to 4 lines of 15 characters each). */
function signChunks(text, n) {
  const words = text.split(/\s+/).filter(Boolean), out = Array.from({ length: n }, () => []);
  if (words.length <= n) { const off = Math.floor((n - words.length) / 2); words.forEach((w, i) => out[off + i].push(w)); }
  else { const per = Math.ceil(words.length / n); words.forEach((w, i) => out[Math.min(n - 1, Math.floor(i / per))].push(w)); }
  return out.map((ws) => { const lines = []; for (const w of ws) { const l = lines.at(-1); if (l != null && (l + " " + w).length <= 15) lines[lines.length - 1] = l + " " + w; else lines.push(w.slice(0, 15)); } return lines.slice(0, 4); });
}

